import{l as o,a,c as l,a6 as i}from"./chunks/framework.CVVsdWKy.js";const h=JSON.parse('{"title":"FHS 文件系统层次结构标准","description":"","frontmatter":{},"headers":[],"relativePath":"blog/linux/fhs.md","filePath":"blog/linux/fhs.md"}'),c={name:"blog/linux/fhs.md"};function t(s,e,d,r,n,p){return a(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="fhs-文件系统层次结构标准" tabindex="-1">FHS 文件系统层次结构标准 <a class="header-anchor" href="#fhs-文件系统层次结构标准" aria-label="Permalink to &quot;FHS 文件系统层次结构标准&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>FHS（Filesystem Hierarchy Stardard）是一个为类 Unix 定义的目录结构和目录内容的规范。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>NixOS 有专有的文件系统结构，通过 symlink 创建了 FHS 标准相关的目录结构。</p></div><h2 id="为什么" tabindex="-1">为什么 <a class="header-anchor" href="#为什么" aria-label="Permalink to &quot;为什么&quot;">​</a></h2><p>提供一致性和可预测性，使用户和软件能更容易地找到和管理文件。</p><h2 id="主要标准内容" tabindex="-1">主要标准内容 <a class="header-anchor" href="#主要标准内容" aria-label="Permalink to &quot;主要标准内容&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p>程序包：程序安装目录的完整内容，包含可执行文件、依赖库、静态资源等</p><p>可执行程序：程序安装后的可执行文件，通常关联 PATH 路径方便命令行直接访问运行，或生成桌面图标方便双击运行</p></div><ul><li><code>/</code>：根目录</li><li><code>/boot</code>：存放启动加载器、内核</li><li><code>/etc</code>：存放全局系统配置</li><li><code>/bin</code>：存放可执行文件，所有用户可访问</li><li><code>/sbin</code>：存放管理员可执行文件，可选</li><li><code>/lib</code>：存放共享库，供 <code>/bin</code> 和 <code>/sbin</code> 中的程序（可执行文件）使用</li><li><code>/usr</code>：Unix System Resources。当前用户程序、数据、库。其中 <code>/usr/local</code> 中存放程序包（非 apt 安装，本地手动安装），避免与系统软件冲突，<code>/usr/local/bin</code> 中存放可执行文件，已默认加入到 PATH 环境变量中</li><li><code>/opt</code>：存放独立大型程序包，通常是非默认安装的程序</li><li><code>/var</code>：存放可变数据：日志、邮件等</li></ul><h3 id="○-usr" tabindex="-1">○ /usr <a class="header-anchor" href="#○-usr" aria-label="Permalink to &quot;○ /usr&quot;">​</a></h3><p>Unix System Resources</p><p>用于存放系统级、所有用户共享的用户空间程序、库、文档、字体、头文件等。其中，<code>/usr/local</code> 中的资源由系统管理员手动管理，<code>/usr</code> 中其他目录由包管理器（apt 等）管理。</p><p>例如：</p><ul><li><code>/usr/local/share/fonts</code> 存放系统级字体</li><li><code>/usr/bin</code> 存放包管理器安装的程序</li></ul><h3 id="○-opt" tabindex="-1">○ /opt <a class="header-anchor" href="#○-opt" aria-label="Permalink to &quot;○ /opt&quot;">​</a></h3><p>optional</p><p>安装到系统全局的可选软件包。有系统用户安装，其他用户仅可读可执行。</p>',17)])])}const b=o(c,[["render",t]]);export{h as __pageData,b as default};
